function searchDosiya(query, topK = 4) {
  const words = query.trim().split(/\s+/).filter(w => w.length > 1);
  if (!words.length) return [];
  const scored = DOSIYA_CHUNKS.map(chunk => {
    let score = 0;
    for (const w of words) if (chunk.includes(w)) score++;
    return { chunk, score };
  });
  return scored.filter(x => x.score > 0).sort((a,b) => b.score - a.score).slice(0, topK).map(x => x.chunk);
}

const SYSTEM_PROMPT = `أنت مساعد OJ الذكي — مساعد تعليمي متخصص في الكيمياء للمرحلة الثانوية وفق المنهاج الفلسطيني، تحت إشراف الأستاذ عمر جيتاوي.
مصادرك الوحيدة: دوسيات الأستاذ عمر جيتاوي والكتاب المدرسي الفلسطيني فقط.
شخصيتك: هادئ، صبور، مشجع، دقيق. ناد الطالب بـ"يا بطل".
اللغة: العربية الفصحى. مصطلحات المنهاج الفلسطيني فقط (طاقة التأين، الفلك، المستويات الفرعية الفرضية).
الفهم أهم من الحفظ. لا تعطِ إجابة حسابية نهائية مباشرة. انهِ بسؤال تفكيري.
إذا لم تجد المعلومة قل: "لم أجد هذه المعلومة في دوسيات الأستاذ عمر."`;

export async function POST(req) {
  try {
    const { messages, userText } = await req.json();

    const chunks = searchDosiya(userText, 4);
    const ctx = chunks.length
      ? "\n\n[مقتطفات من دوسية الأستاذ عمر جيتاوي]:\n" + chunks.map(c => c.substring(0, 500)).join("\n---\n") + "\n[نهاية المقتطفات]"
      : "";

    const apiMessages = messages.map((m, i) => ({
      role: m.role === 'assistant' ? 'model' : 'user',
      parts: [{ text: i === messages.length - 1 ? m.content + ctx : m.content }]
    }));

    const GEMINI_KEY = process.env.GEMINI_API_KEY;
    const response = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${GEMINI_KEY}`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          system_instruction: { parts: [{ text: SYSTEM_PROMPT }] },
          contents: apiMessages,
          generationConfig: { maxOutputTokens: 1500, temperature: 0.7 }
        })
      }
    );

    const data = await response.json();
    if (!response.ok) {
      return NextResponse.json({ error: data.error?.message || 'API error' }, { status: response.status });
    }

    const reply = data.candidates?.[0]?.content?.parts?.[0]?.text || 'لم تصل إجابة';
    return NextResponse.json({ reply });

  } catch (e) {
    return NextResponse.json({ error: e.message }, { status: 500 });
  }
}
